          "description": {
            "title": "Description",
            "type": "string",
            "description": "What does this service do?"
          },
          "owner": {
            "title": "Owner",
            "type": "string",
            "description": "The team that owns this service",
            "ui:field": "EntityPicker",
            "ui:options": {
              "catalogFilter": {
