            "ui:options": {
              "catalogFilter": {
                "kind": [
                  "System"
                ]
              }
            }
          }
        }
      },
      {
        "title": "Java Configuration",
        "required": [
          "groupId",
          "artifactId",
          "javaPackageName"
        ],
        "properties": {
          "groupId": {
            "title": "Group ID",
            "type": "string",
            "default": "com.parasol",
            "description": "Maven group ID"
          },
          "artifactId": {
            "title": "Artifact ID",
            "type": "string",
            "description": "Maven artifact ID (defaults to service name)"
          },
          "javaPackageName": {
            "title": "Java Package",
            "type": "string",
            "default": "com.parasol",
            "description": "Base Java package name"
          },
          "port": {
            "title": "Port",
            "type": "number",
            "default": 8080,
            "description": "HTTP port for the service"
          }
        }
      }
    ],
    "steps": [
      {
        "id": "template",
        "name": "Fetch Service Skeleton",
        "action": "fetch:template",
        "input": {
          "url": "./skeleton",
          "values": {
            "name": "${{ parameters.name }}",
            "description": "${{ parameters.description }}",
            "groupId": "${{ parameters.groupId }}",
            "artifactId": "${{ parameters.artifactId }}",
            "javaPackageName": "${{ parameters.javaPackageName }}",
            "port": "${{ parameters.port }}"
          }
        }
      },
      {
        "id": "catalogTemplate",
        "name": "Fetch Catalog Info",
        "action": "fetch:template",
        "input": {
          "url": "../skeletons/catalog-info/",
          "values": {
            "name": "${{ parameters.name }}",
            "description": "${{ parameters.description }}",
            "owner": "${{ parameters.owner }}",
            "system": "${{ parameters.system }}",
            "stack": "java"
          }
        }
      }
    ],
    "output": {
      "links": [
        {
          "title": "Service Skeleton",
          "icon": "catalog",
          "entityRef": "${{ steps.catalogTemplate.output.entityRef }}"
        }
      ]
    }
  },
  "relations": [
    {
      "type": "ownedBy",
      "targetRef": "group:default/parasol-platform-engineering"
    }
  ]
}

